const _rumTR: Dict = { "rumor.hakaret.0":"%1, %2'i herkesin içinde aşağılamış.", "rumor.hakaret.1":"Duydun mu? %1 ağzına geleni söylemiş %2'e.", "rumor.tehdit.0":"%1, %2'i tehdit etmiş — gözü dönmüş diyorlar.","rumor.tehdit.1":"%1'in %2'e söyledikleri kapı arkasından duyulmuş; ağızdan çıkan söz değil, bıçakmış.", "rumor.saldiri.0":"%1, %2'e saldırmış. Kan dökülmüş.", "rumor.saldiri.1":"Çarşıda konuşulan o: %1 yumruklarıyla konuşuyormuş.", "rumor.kacirma.0":"%1 adam kaçırıyormuş! %2'in başına gelen herkesin dilinde.", "rumor.hirsizlik_tanigi.0":"%2, %1'i el işi üstünde görmüş. Eli uzunmuş diyorlar.", "rumor.suc_tanigi.0":"%1'in karanlık işler çevirdiğini %2 kendi gözüyle görmüş.", "rumor.dolandiricilik.0":"%1 güveni boşa çıkarmış; %2'i dolandırmış diyorlar.","rumor.dolandiricilik.1":"%1 sözde ortaklık kurup %2'in sermayesini yürütmüş; kese boşalınca ortak da kaybolmuş. Tez zengin olanın izini sür, demişler.", "rumor.somuru.0":"%1, %2'in derdini koz yapmış. İçten pazarlıklıymış.","rumor.somuru.1":"%2 bir sır vermiş %1'e; ertesi gün o sır pazarın diline düşmüş. Emanete göz dikenin adı böyle çıkar.", "rumor.iftira.0":"%1'in dili zehirli — %2'in arkasından kuyu kazmış.","rumor.iftira.1":"%2 hakkındaki o çirkin lafın kaynağı belliymiş: %1. Kuyu kazan kuyuya düşer, diyorlar.", "rumor.alay.0":"%1, %2'le alay etmiş; küçük düşürmeyi seviyormuş.","rumor.alay.1":"Çarşı ortasında %2'i güldürü konusu yapan %1'miş; gülenler sonra utanmış.", "rumor.yakinima_zarar.0":"%1 yüzünden %2'in ocağına ateş düşmüş.","rumor.yakinima_zarar.1":"%1'in bir sözü yüzünden %2'in oğlu işten olmuş; söz kılıçtan keskin, derler — işte bu yüzden.", "rumor.flort_tanigi.0":"%1'in gözü dışarıdaymış; %2 görmüş.", "rumor.flort_tanigi.1":"%1 gönül işlerinde pek hızlıymış, öyle diyorlar.", "rumor.reddedilme.0":"%1 kapı kapı gönül dileniyormuş; %2'den reddi yemiş.","rumor.reddedilme.1":"%1 dünürlüğe gitmiş de %2'in hanesinden boş dönmüş; kapı yüzüne kapanmamış ama açılmamış da.", "rumor.comert_hediye.0":"%1 eli açık biriymiş; %2'e verdiği hediye dillerde.","rumor.comert_hediye.1":"%2 aldığı hediyeyi çarşıda herkese göstermiş; %1 vermeyi biliyor, diyorlar.", "rumor.sadaka.0":"%1 fakir fukarayı gözetiyormuş; %2 de nasiplenmiş.","rumor.sadaka.1":"Cuma sabahı tekke önünde kese açılmış; %1 sormadan vermiş, %2 gözleriyle görmüş.", "rumor.yardim.0":"%1, %2'in zor gününde yanında durmuş. Yürek dediğin böyle olur.","rumor.yardim.1":"%2'in damı çökmüş gece yarısı; ilk gelen %1 olmuş. Böyle komşuluk kaldı mı?", "rumor.borc_kurtarma.0":"%1, %2'i borç batağından çekip çıkarmış. Böylesi az bulunur.","rumor.borc_kurtarma.1":"Tefeci %2'in kapısına dikilmişken %1 borcu sessizce kapatmış; kimseye söylememiş, %2 sonradan öğrenmiş. İyilik böyle yapılır.", "rumor.hayat_kurtarma.0":"%1, %2'in hayatını kurtarmış! Kahraman diyorlar.","rumor.hayat_kurtarma.1":"Sel sularına kapılan %2'i %1 saçından çekip çıkarmış; ikisi de titreye titreye kıyıya varmış. Böyle yiğitlik unutulmaz.", "rumor.savunma.0":"%1, %2'i yalnız bırakmamış; mertçe önüne dikilmiş.","rumor.savunma.1":"Pazarda üç kişi %2'in üstüne yürümüş; %1 tek başına araya girip dağıtmış. Arkadaşını yalnız bırakmayan adam.", "rumor.ibadet_tanigi.0":"%1'i dualarında gören var; dindar biriymiş.","rumor.ibadet_tanigi.1":"Gece yarısı mescitte tek başına %1'i görmüşler; kimse yokken de aynıymış. Riyasız kulluk diyorlar buna.", "rumor.ihanet.0":"%1 güvenilmez biriymiş; %2 sırtından bıçaklanmış.", "rum.title":"Hakkındaki Söylentiler", "rum.none":"Şu an dilden dile dolaşan bir lafın yok.", "rum.bribe":"Rüşvetle ağızları kapatmaya çalıştın ama biri boşboğazlık etti: iş büyüdü.", "rum.intensity":"şiddet", "rum.confront.win":"Yüzüne karşı sözünü yutmak zorunda kaldı; söylenti söndü.", "rum.confront.lose":"Yüzleşme ters tepti; söylenti alevlendi.", "rum.spread.win":"Sözü sen de salladın; namın büyüyor.", "rum.silence.win":"%1 akçe doğru ellere dağıldı; konuşan diller unutkanlaştı." };
const _rumEN: Dict = { "rumor.hakaret.0":"%1 humiliated %2 in front of everyone.", "rumor.hakaret.1":"Did you hear? %1 gave %2 a real mouthful.", "rumor.tehdit.0":"%1 threatened %2 — gone clean out of their mind, they say.","rumor.tehdit.1":"What %1 said to %2 was heard through the door; not words, they say — knives.", "rumor.saldiri.0":"%1 attacked %2. Blood was spilled.", "rumor.saldiri.1":"It's the talk of the market: %1 lets their fists do the talking.", "rumor.kacirma.0":"%1 is snatching folk away! What befell %2 is on every tongue.", "rumor.hirsizlik_tanigi.0":"%2 caught %1 red-handed. Sticky fingers, they say.", "rumor.suc_tanigi.0":"%2 saw with their own eyes that %1 is mixed up in dark dealings.", "rumor.dolandiricilik.0":"%1 betrayed a trust; cheated %2, they say.","rumor.dolandiricilik.1":"%1 set up a sham partnership and walked off with %2's capital; when the purse was empty, so was the partner. Follow the trail of the suddenly rich, they say.", "rumor.somuru.0":"%1 turned %2's troubles into a bargaining chip. A scheming sort.","rumor.somuru.1":"%2 confided a secret to %1; the next day it was on every tongue in the market. That is how the name of one who betrays a trust gets out.", "rumor.iftira.0":"%1 has a poisoned tongue — dug a pit behind %2's back.","rumor.iftira.1":"That ugly tale about %2 has a known source: %1. Dig a pit for another, they say, and you fall in it yourself.", "rumor.alay.0":"%1 mocked %2; loves to belittle others, they say.","rumor.alay.1":"It was %1 who made %2 the joke of the bazaar; those who laughed felt shame after.", "rumor.yakinima_zarar.0":"Because of %1, fire fell on %2's hearth.","rumor.yakinima_zarar.1":"Because of a word from %1, the son of %2 lost his post; a word is sharper than a blade, they say — this is why.", "rumor.flort_tanigi.0":"%1's eye wanders elsewhere; %2 saw it.", "rumor.flort_tanigi.1":"%1 is quick in affairs of the heart, so they say.", "rumor.reddedilme.0":"%1 begs for love door to door; got turned away by %2.","rumor.reddedilme.1":"%1 went to ask for a match and returned empty-handed from %2's house; the door was not shut in his face, but neither did it open.", "rumor.comert_hediye.0":"%1 is open-handed; the gift given to %2 is on everyone's lips.","rumor.comert_hediye.1":"%2 showed that gift around the whole bazaar; %1 knows how to give, they say.", "rumor.sadaka.0":"%1 looks after the poor and needy; %2 got a share too.","rumor.sadaka.1":"A purse was opened outside the lodge on Friday morning; %1 gave without asking questions — %2 saw it happen.", "rumor.yardim.0":"%1 stood by %2 on a hard day. A true-hearted soul.","rumor.yardim.1":"The roof of %2 gave way in the middle of the night; %1 was the first to arrive. Where do you still find neighbors like that?", "rumor.borc_kurtarma.0":"%1 pulled %2 out of the mire of debt. Such folk are rare.","rumor.borc_kurtarma.1":"With the moneylender at %2's door, %1 quietly cleared the debt; told no one, and %2 learned of it only later. That is how a kindness is done.", "rumor.hayat_kurtarma.0":"%1 saved %2's life! A hero, they call them.","rumor.hayat_kurtarma.1":"They say %1 pulled %2 by the hair from the flood waters; both reached the bank trembling. Such courage is not forgotten.", "rumor.savunma.0":"%1 didn't leave %2 alone; stood before them bravely.","rumor.savunma.1":"Three men set upon %2 in the market; %1 stepped in alone and broke it up. A man who does not abandon his friend.", "rumor.ibadet_tanigi.0":"Some have seen %1 at their prayers; a devout one.","rumor.ibadet_tanigi.1":"They saw %1 alone in the mosque at midnight; the same when no one was watching. Worship without show, they call it.", "rumor.ihanet.0":"%1 can't be trusted; %2 was stabbed in the back.", "rum.title":"Rumors About You", "rum.none":"No talk is going from tongue to tongue about you right now.", "rum.bribe":"You tried to buy their silence, but someone blabbed: it only grew worse.", "rum.intensity":"heat", "rum.confront.win":"They had to swallow their words to your face; the rumor died.", "rum.confront.lose":"The confrontation backfired; the rumor flared up.", "rum.spread.win":"You spread the word yourself; your renown grows.", "rum.silence.win":"%1 coins went to the right hands; loose tongues grew forgetful." };
const _rumES: Dict = { "rumor.hakaret.0":"%1 humilló a %2 delante de todo el mundo.", "rumor.hakaret.1":"¿Te enteraste? %1 le soltó de todo a %2.", "rumor.tehdit.0":"%1 amenazó a %2 — dicen que se le nubló la vista.","rumor.tehdit.1":"Lo que %1 le dijo a %2 se oyó tras la puerta; no eran palabras, dicen — eran cuchillos.", "rumor.saldiri.0":"%1 atacó a %2. Hubo sangre.", "rumor.saldiri.1":"En el mercado no se habla de otra cosa: %1 habla con los puños.", "rumor.kacirma.0":"¡%1 anda secuestrando gente! Lo que le pasó a %2 está en boca de todos.", "rumor.hirsizlik_tanigi.0":"%2 vio a %1 con las manos en la masa. Dicen que tiene la mano larga.", "rumor.suc_tanigi.0":"%2 vio con sus propios ojos cómo %1 andaba en asuntos turbios.", "rumor.dolandiricilik.0":"%1 traicionó la confianza; dicen que estafó a %2.","rumor.dolandiricilik.1":"%1 montó una sociedad falsa y se llevó el capital de %2; vaciada la bolsa, se esfumó el socio. Sigue el rastro del que se enriquece de golpe, dicen.", "rumor.somuru.0":"%1 se aprovechó de la desgracia de %2. Resultó ser un falso.","rumor.somuru.1":"%2 confió un secreto a %1; al día siguiente andaba en boca de todo el mercado. Así se hace el nombre de quien traiciona una confianza.", "rumor.iftira.0":"%1 tiene la lengua venenosa — le cavó la fosa a %2 por la espalda.","rumor.iftira.1":"Aquel feo rumor sobre %2 tiene fuente conocida: %1. Quien cava una fosa, dicen, cae en ella.", "rumor.alay.0":"%1 se burló de %2; dicen que le encanta humillar a la gente.","rumor.alay.1":"Fue %1 quien hizo de %2 la burla del bazar; los que rieron sintieron vergüenza después.", "rumor.yakinima_zarar.0":"Por culpa de %1, el hogar de %2 se vino abajo.","rumor.yakinima_zarar.1":"Por una palabra de %1, el hijo de %2 se quedó sin puesto; la palabra es más afilada que la espada, dicen — por esto.", "rumor.flort_tanigi.0":"%1 anda con el ojo puesto en otras; %2 lo vio.", "rumor.flort_tanigi.1":"Dicen que %1 va muy ligero en asuntos del corazón.", "rumor.reddedilme.0":"%1 anda mendigando amor de puerta en puerta; %2 lo rechazó.","rumor.reddedilme.1":"%1 fue a pedir concierto de boda y volvió con las manos vacías de casa de %2; la puerta no se le cerró en las narices, pero tampoco se abrió.", "rumor.comert_hediye.0":"Dicen que %1 es de mano abierta; el regalo que le dio a %2 anda en boca de todos.","rumor.comert_hediye.1":"%2 enseñó el regalo por todo el bazar; %1 sabe dar, dicen.", "rumor.sadaka.0":"Dicen que %1 cuida de los pobres y necesitados; a %2 también le tocó su parte.","rumor.sadaka.1":"El viernes por la mañana se abrió una bolsa ante el tekke; %1 dio sin preguntar — %2 lo vio.", "rumor.yardim.0":"%1 estuvo junto a %2 en su día más difícil. Palabra firme, corazón firme.","rumor.yardim.1":"El techo de %2 se vino abajo a medianoche; %1 llegó primero. ¿Dónde quedan vecinos así?", "rumor.borc_kurtarma.0":"%1 sacó a %2 del pozo de las deudas. De esos hay pocos.","rumor.borc_kurtarma.1":"Con el usurero a la puerta de %2, %1 saldó la deuda en silencio; no se lo dijo a nadie, y %2 lo supo después. Así se hace un favor.", "rumor.hayat_kurtarma.0":"¡%1 le salvó la vida a %2! Dicen que es un héroe.","rumor.hayat_kurtarma.1":"Dicen que %1 sacó a %2 de las aguas de la riada agarrándolo del cabello; ambos llegaron a la orilla temblando. Semejante valor no se olvida.", "rumor.savunma.0":"%1 no dejó solo a %2; se plantó delante con valentía.","rumor.savunma.1":"Tres hombres se abalanzaron sobre %2 en el mercado; %1 se interpuso solo y los dispersó. Un hombre que no abandona a su amigo.", "rumor.ibadet_tanigi.0":"Hay quien vio a %1 en sus oraciones; dicen que es muy devoto.","rumor.ibadet_tanigi.1":"Vieron a %1 solo en la mezquita a medianoche; igual cuando nadie miraba. Devoción sin ostentación, lo llaman.", "rumor.ihanet.0":"Dicen que %1 no es de fiar; a %2 lo apuñaló por la espalda.", "rum.title":"Rumores sobre ti", "rum.none":"Ahora mismo no hay ninguna habladuría sobre ti.", "rum.bribe":"Intentaste cerrar bocas con sobornos, pero alguien se fue de la lengua: la cosa se hizo más grande.", "rum.intensity":"intensidad", "rum.confront.win":"Tuvo que tragarse sus palabras ante ti; el rumor se apagó.", "rum.confront.lose":"El enfrentamiento salió mal; el rumor se avivó.", "rum.spread.win":"Tú mismo corriste la voz; tu fama crece.", "rum.silence.win":"%1 akçe fueron a las manos adecuadas; las lenguas sueltas olvidaron." };
const _rumPT: Dict = { "rumor.hakaret.0":"%1 humilhou %2 à frente de toda a gente.", "rumor.hakaret.1":"Ouviste? %1 disse o que lhe veio à boca a %2.", "rumor.tehdit.0":"%1 ameaçou %2 — dizem que perdeu a cabeça.","rumor.tehdit.1":"O que %1 disse a %2 ouviu-se por trás da porta; não eram palavras, dizem — eram facas.", "rumor.saldiri.0":"%1 atacou %2. Houve sangue derramado.", "rumor.saldiri.1":"É o que se fala no mercado: %1 fala é com os punhos.", "rumor.kacirma.0":"%1 anda a raptar gente! O que aconteceu a %2 está na boca de todos.", "rumor.hirsizlik_tanigi.0":"%2 viu %1 com a mão na obra. Dizem que tem a mão comprida.", "rumor.suc_tanigi.0":"%2 viu com os próprios olhos %1 a tramar negócios sombrios.", "rumor.dolandiricilik.0":"%1 traiu a confiança; dizem que enganou %2.","rumor.dolandiricilik.1":"%1 montou uma sociedade falsa e levou o capital de %2; esvaziada a bolsa, sumiu o sócio. Segue o rasto de quem enriquece de repente, dizem.", "rumor.somuru.0":"%1 fez da desgraça de %2 uma moeda de troca. Anda com segundas intenções.","rumor.somuru.1":"%2 confiou um segredo a %1; no dia seguinte andava na boca de todo o mercado. É assim que se faz o nome de quem trai uma confiança.", "rumor.iftira.0":"A língua de %1 é veneno — andou a cavar a cova de %2 pelas costas.","rumor.iftira.1":"Aquele boato feio sobre %2 tem fonte conhecida: %1. Quem cava a cova, dizem, nela cai.", "rumor.alay.0":"%1 troçou de %2; parece que gosta de humilhar os outros.","rumor.alay.1":"Foi %1 quem fez de %2 a chacota do bazar; quem riu sentiu vergonha depois.", "rumor.yakinima_zarar.0":"Por culpa de %1, caiu o fogo no lar de %2.","rumor.yakinima_zarar.1":"Por uma palavra de %1, o filho de %2 ficou sem lugar; a palavra é mais afiada que a espada, dizem — é por isto.", "rumor.flort_tanigi.0":"%1 anda de olho posto lá fora; %2 viu.", "rumor.flort_tanigi.1":"%1 é bem ligeiro nos assuntos do coração, é o que dizem.", "rumor.reddedilme.0":"%1 anda de porta em porta a mendigar amores; levou com a porta na cara de %2.","rumor.reddedilme.1":"%1 foi pedir um casamento e voltou de mãos vazias da casa de %2; a porta não se lhe fechou na cara, mas também não se abriu.", "rumor.comert_hediye.0":"%1 é pessoa de mão aberta; a prenda que deu a %2 anda em todas as bocas.","rumor.comert_hediye.1":"%2 mostrou o presente pelo bazar inteiro; %1 sabe dar, dizem.", "rumor.sadaka.0":"%1 olha pelos pobres e desvalidos; %2 também teve o seu quinhão.","rumor.sadaka.1":"Na sexta de manhã abriu-se uma bolsa diante do tekke; %1 deu sem perguntar — %2 viu.", "rumor.yardim.0":"%1 esteve ao lado de %2 no dia mau. Palavra firme, coração firme.","rumor.yardim.1":"O telhado de %2 caiu a meio da noite; %1 chegou primeiro. Onde há ainda vizinhos assim?", "rumor.borc_kurtarma.0":"%1 tirou %2 do atoleiro das dívidas. Gente assim raramente se vê.","rumor.borc_kurtarma.1":"Com o agiota à porta de %2, %1 saldou a dívida em silêncio; não disse a ninguém, e %2 soube-o depois. É assim que se faz um favor.", "rumor.hayat_kurtarma.0":"%1 salvou a vida de %2! Chamam-lhe herói.","rumor.hayat_kurtarma.1":"Dizem que %1 tirou %2 das águas da cheia agarrando-o pelos cabelos; ambos chegaram à margem a tremer. Tal coragem não se esquece.", "rumor.savunma.0":"%1 não deixou %2 sozinho; pôs-se à frente dele com bravura.","rumor.savunma.1":"Três homens avançaram sobre %2 no mercado; %1 meteu-se sozinho e dispersou-os. Um homem que não abandona o amigo.", "rumor.ibadet_tanigi.0":"Há quem tenha visto %1 nas suas orações; é pessoa devota.","rumor.ibadet_tanigi.1":"Viram %1 sozinho na mesquita à meia-noite; igual quando ninguém via. Devoção sem ostentação, chamam-lhe.", "rumor.ihanet.0":"%1 não é de confiança; %2 foi apunhalado pelas costas.", "rum.title":"Rumores sobre Ti", "rum.none":"Por agora não corre nenhuma boca a teu respeito.", "rum.bribe":"Tentaste calar as bocas com suborno, mas alguém deu à língua: a coisa cresceu.", "rum.intensity":"intensidade", "rum.confront.win":"Teve de engolir as palavras à tua frente; o rumor morreu.", "rum.confront.lose":"O confronto saiu pela culatra; o rumor inflamou-se.", "rum.spread.win":"Espalhaste tu mesmo a palavra; a tua fama cresce.", "rum.silence.win":"%1 akçe foram às mãos certas; as línguas soltas esqueceram." };
const _rumAR: Dict = { "rumor.hakaret.0":"يقولون إنّ %1 أهان %2 على مرأى من الناس.", "rumor.hakaret.1":"أسمعتَ؟ يُروى أنّ %1 سَبَّ %2 بأقذع الكلام.", "rumor.tehdit.0":"يقولون إنّ %1 هدّد %2، وقد طاش عقله كما يُحكى.","rumor.tehdit.1":"ما قيل بين %1 و%2 سُمع من خلف الباب؛ يقولون ما كان كلاما بل سكاكين.", "rumor.saldiri.0":"يُروى أنّ %1 اعتدى على %2، حتى سُفك الدم.", "rumor.saldiri.1":"هذا حديث السوق: يقولون إنّ %1 لا يُحاجج إلّا بقبضتيه.", "rumor.kacirma.0":"يقولون إنّ %1 يخطف الناس! وما جرى لـ%2 على كلّ لسان.", "rumor.hirsizlik_tanigi.0":"يُروى أنّ %2 رأى %1 متلبّسًا بالسرقة، ويقولون إنّ يده طويلة.", "rumor.suc_tanigi.0":"يقولون إنّ %2 رأى بأمّ عينه %1 يدبّر أعمالًا مظلمة.", "rumor.dolandiricilik.0":"يقولون إنّ %1 خان الأمانة واحتال على %2.","rumor.dolandiricilik.1":"أقام %1 شراكة زائفة واستولى على رأس مال %2؛ ولما خلا الكيس اختفى الشريك. تتبّع أثر من يثرى فجأة، كما يقولون.", "rumor.somuru.0":"يُروى أنّ %1 اتّخذ من محنة %2 ورقةً يساوم بها، فما أخبثه من رجل.","rumor.somuru.1":"أفضى %2 بسر إلى %1؛ وفي الغد صار على كل لسان في السوق. هكذا يُعرف من يخون الأمانة.", "rumor.iftira.0":"يقولون إنّ لسان %1 مسموم، وقد حفر لـ%2 بئرًا من خلفه.","rumor.iftira.1":"تلك الفرية على %2 مصدرها معروف: %1. ومن حفر حفرة لأخيه وقع فيها، كما يقولون.", "rumor.alay.0":"يُروى أنّ %1 سخر من %2، ويقولون إنّه يلذّ له إذلال الناس.","rumor.alay.1":"صار %2 أضحوكة السوق، والاسم وراء ذلك %1؛ ومن ضحكوا يومها ندموا بعدها.", "rumor.yakinima_zarar.0":"يقولون إنّ بسبب %1 أُضرمت النار في دار %2.","rumor.yakinima_zarar.1":"بسبب كلمة من %1 فقد ابن %2 عمله؛ الكلمة أحدّ من السيف، يقولون — ولهذا.", "rumor.flort_tanigi.0":"يقولون إنّ عين %1 تشرد إلى الغريبات، وقد رآه %2.", "rumor.flort_tanigi.1":"يُروى أنّ %1 خفيفٌ في أمور القلب، هكذا يقولون.", "rumor.reddedilme.0":"يقولون إنّ %1 يستجدي الوصال من باب إلى باب، وقد ردّه %2 خائبًا.","rumor.reddedilme.1":"ذهب %1 يخطب فعاد خالي اليدين من بيت %2؛ لم يُغلق الباب في وجهه لكنه لم يُفتح أيضا.", "rumor.comert_hediye.0":"يقولون إنّ %1 رجلٌ سخيّ اليد، وهديّته إلى %2 على كلّ لسان.","rumor.comert_hediye.1":"طاف %2 بالسوق يري الناس هديته؛ ويقولون إن عطاء %1 لا يخيب.", "rumor.sadaka.0":"يُروى أنّ %1 يرعى الفقراء والمساكين، وقد نال %2 من خيره.","rumor.sadaka.1":"صباح الجمعة انفتح كيس أمام التكية؛ عطاء من %1 بلا سؤال، و%2 شاهد على ذلك.", "rumor.yardim.0":"يقولون إن لـ%2 سندا يوم العسرة اسمه %1؛ وفاء قل نظيره.","rumor.yardim.1":"انهار سقف %2 في منتصف الليل؛ وأول الواصلين %1. أين مثل هذا الجوار؟", "rumor.borc_kurtarma.0":"يُروى أنّ %1 انتشل %2 من وحل الديون، ومثله قليلٌ نادر.","rumor.borc_kurtarma.1":"والمرابي على باب %2، سدّد %1 الدين بصمت؛ ولم يخبر أحدا، وعلم %2 بذلك لاحقا. هكذا يُصنع المعروف.", "rumor.hayat_kurtarma.0":"يقولون إنّ %1 أنقذ حياة %2! ويدعونه بطلًا.","rumor.hayat_kurtarma.1":"يقولون إن %1 انتشل %2 من مياه الفيضان من شعره؛ فبلغا الضفة يرتجفان. مثل هذه الشجاعة لا تُنسى.", "rumor.savunma.0":"يُروى أنّ %1 لم يخذل %2، بل وقف دونه وقفة الأبطال.","rumor.savunma.1":"هجم ثلاثة على %2 في السوق؛ فتوسط %1 وحده وفرّقهم. رجل لا يتخلى عن صديقه.", "rumor.ibadet_tanigi.0":"ثمّة من رأى %1 في صلواته، ويقولون إنّه رجلٌ تقيّ.","rumor.ibadet_tanigi.1":"رأوا %1 وحده في المسجد منتصف الليل؛ وكان كذلك حين لا يراه أحد. عبادة بلا رياء يسمونها.", "rumor.ihanet.0":"يقولون إنّ %1 رجلٌ لا يُؤتمن، وقد طُعن %2 من خلف ظهره.", "rum.title":"الإشاعات عنك", "rum.none":"ليس ثمّة قولٌ يتناقله الناس عنك الآن.", "rum.bribe":"حاولتَ إسكات الألسنة بالرشوة، لكنّ أحدهم ثرثر، فاستفحل الأمر.", "rum.intensity":"الحِدّة", "rum.confront.win":"اضطُرّ إلى ابتلاع كلامه في وجهك؛ فخمدت الإشاعة.", "rum.confront.lose":"ارتدّت المواجهة عليك؛ فاشتعلت الإشاعة.", "rum.spread.win":"نشرتَ الخبر بنفسك؛ فعلا صيتُك.", "rum.silence.win":"وُزِّعت %1 قطعة نقدية في الأيدي المناسبة؛ فنسيت الألسنة الثرثارة." };
const _rumRU: Dict = { "rumor.hakaret.0":"Говорят, %1 опозорил %2 при всём честном народе.", "rumor.hakaret.1":"Слыхал? %1 наговорил %2 такого, что уши вянут.", "rumor.tehdit.0":"Говорят, %1 пригрозил %2 — совсем, мол, рассудок потерял.","rumor.tehdit.1":"Что было сказано %2 из уст %1 — слышали через дверь; не слова, говорят, а ножи.", "rumor.saldiri.0":"Говорят, %1 набросился на %2. Кровь пролилась.", "rumor.saldiri.1":"На базаре только и судачат: %1, мол, кулаками разговаривает.", "rumor.kacirma.0":"%1 людей похищает! Что стряслось с %2 — у всех на устах.", "rumor.hirsizlik_tanigi.0":"%2 застал %1 за нечистым делом. На руку нечист, говорят.", "rumor.suc_tanigi.0":"%2 своими глазами видел, как %1 тёмные дела творит.", "rumor.dolandiricilik.0":"%1 доверие обманул; %2, говорят, надул.","rumor.dolandiricilik.1":"%1 затеял мнимое товарищество и увёл капитал %2; опустел кошель — исчез и компаньон. Ищи след того, кто вдруг разбогател, говорят.", "rumor.somuru.0":"Говорят, %1 беду %2 себе в выгоду обратил. Двуличный, мол.","rumor.somuru.1":"%2 доверил тайну %1; назавтра о ней говорил весь базар. Так и расходится слава того, кто предаёт доверие.", "rumor.iftira.0":"У %1 язык что змеиное жало — за спиной у %2 яму копал.","rumor.iftira.1":"У той грязной сплетни про %2 источник известен: %1. Кто роет яму другому, говорят, сам в неё попадёт.", "rumor.alay.0":"Говорят, %1 насмехался над %2; унижать любит.","rumor.alay.1":"За базарной шуткой над %2 стоит имя %1; тем, кто смеялся, после стало стыдно.", "rumor.yakinima_zarar.0":"Из-за %1 в дом %2 беда пришла.","rumor.yakinima_zarar.1":"Из-за слова %1 сын %2 лишился места; слово острее клинка, говорят, — вот почему.", "rumor.flort_tanigi.0":"У %1 глаз на сторону косит; %2 это приметил.", "rumor.flort_tanigi.1":"%1 в сердечных делах больно прыток, так говорят.", "rumor.reddedilme.0":"%1 от двери к двери любви выпрашивает; от %2 от ворот поворот получил.","rumor.reddedilme.1":"%1 пошёл свататься и вернулся ни с чем из дома %2; дверь не захлопнули перед ним, но и не отворили.", "rumor.comert_hediye.0":"%1, говорят, рука щедрая; подарок его для %2 у всех на языке.","rumor.comert_hediye.1":"Весь базар видел у %2 подарок от %1; вот это щедрость, говорят.", "rumor.sadaka.0":"%1 о бедных да убогих печётся; и %2 от него не обделён.","rumor.sadaka.1":"В пятницу утром у текке развязался кошель: %1 подаёт не спрашивая, а %2 — свидетель тому.", "rumor.yardim.0":"Говорят, в чёрный день у %2 нашлась опора — %1. Такое не забывают.","rumor.yardim.1":"У %2 среди ночи рухнула крыша; раньше всех на пороге — %1. Где ещё такие соседи?", "rumor.borc_kurtarma.0":"Говорят, %1 вытащил %2 из долговой ямы. Такое нечасто сыщешь.","rumor.borc_kurtarma.1":"Когда ростовщик стоял у двери %2, %1 тихо погасил долг; никому не сказал, и %2 узнал лишь после. Вот как делают добро.", "rumor.hayat_kurtarma.0":"%1 жизнь %2 спас! Героем величают.","rumor.hayat_kurtarma.1":"Говорят, %1 вытащил %2 из паводка за волосы; оба выбрались на берег, дрожа. Такую отвагу не забывают.", "rumor.savunma.0":"%1 не бросил %2 в беде; доблестно встал на защиту.","rumor.savunma.1":"Трое насели на %2 на базаре; %1 вступился один и разнял их. Человек, что не бросает друга.", "rumor.ibadet_tanigi.0":"Видали %1 за молитвой; человек, мол, набожный.","rumor.ibadet_tanigi.1":"Видели %1 одного в мечети в полночь; таким же и когда никто не смотрел. Служение без показухи, зовут это.", "rumor.ihanet.0":"%1, говорят, человек ненадёжный; %2 в спину предал.", "rum.title":"Слухи о тебе", "rum.none":"Про тебя нынче никаких толков не ходит.", "rum.bribe":"Ты хотел мздой рты позатыкать, да кто-то проболтался: дело только пуще раздулось.", "rum.intensity":"сила", "rum.confront.win":"Ему пришлось проглотить слова тебе в лицо; слух угас.", "rum.confront.lose":"Стычка обернулась против тебя; слух разгорелся.", "rum.spread.win":"Ты сам пустил молву; слава твоя растёт.", "rum.silence.win":"%1 акче ушли в нужные руки; болтливые языки забыли." };
