// İkilemler (id bazlı): .t başlık, .x metin, .c0/.c1 seçim, .r0/.r1 sonuç.
const DIL: Record<Lang, Dict> = {
  tr: { "dil.dilenci.t":"Yol Kenarında Bir Dilenci","dil.dilenci.x":"Titreyen elini sana uzatan yaşlı bir dilenci, bir lokma ekmek diliyor.","dil.dilenci.c0":"Sadaka ver (−5 akçe)","dil.dilenci.r0":"Dilenciye sadaka verdin; içinden bir ferahlık geçti.","dil.dilenci.c1":"Yanından geç","dil.dilenci.r1":"Başını çevirip geçtin. Bakışları arkandan geldi.","dil.kese.t":"Yerde Bir Kese","dil.kese.x":"Çamurun içinde, ağzı akçeyle dolu bir kese buldun. Sahibi görünürde yok.","dil.kese.c0":"Cebe at","dil.kese.r0":"Keseyi cebe attın. Akçe akçedir; ama vicdanın bir an sızladı.","dil.kese.c1":"Sahibini ara","dil.kese.r1":"Keseyi sahibine ulaştırdın. Dürüstlüğün diyarda konuşuldu.","dil.hasta.t":"Hasta Bir Yolcu","dil.hasta.x":"Yol kenarında ateşler içinde yatan bir yolcu yardım istiyor. Hastalık bulaşabilir.","dil.hasta.c0":"Yardım et","dil.hasta.r0":"Yolcuya baktın; biraz halsiz düştün ama vicdanın rahat.","dil.hasta.c1":"Uzak dur","dil.hasta.r1":"Riske girmedin, yoluna devam ettin.","dil.haydut.t":"Yol Kesen Haydut","dil.haydut.x":"Pusudan çıkan bir haydut, geçiş için akçe istiyor.","dil.haydut.c0":"Akçeyi ver (−20)","dil.haydut.r0":"İstediğini verip kurtuldun. Cebin hafifledi.","dil.haydut.c1":"Karşı koy","dil.haydut.r1":"Haydutla boğuştun; yara aldın ama adın korkusuz diye anıldı.","dil.tuccar.t":"Tüccarın Teklifi","dil.tuccar.x":"Bir tüccar, kervana ortak olursan kârı katlayacağını söylüyor. Ya da batarsın.","dil.tuccar.c0":"Yatırım yap (−40)","dil.tuccar.r0":"Kervan sağ döndü; yatırımın katlanarak geri geldi.","dil.tuccar.c1":"Riske girme","dil.tuccar.r1":"Teklifi geri çevirdin. Belki de doğrusu buydu.","dil.dervis.t":"Gezgin Bir Derviş","dil.dervis.x":"Yorgun bir derviş, bir gece konukluk karşılığında hikmetli sözler vaat ediyor.","dil.dervis.c0":"Konuk et","dil.dervis.r0":"Dervişin sohbetinden bir şeyler öğrendin (özellik puanı kazandın).","dil.dervis.c1":"Geri çevir","dil.dervis.r1":"Kapını açmadın; derviş sessizce uzaklaştı.","dil.kavga.t":"Meydanda Kavga","dil.kavga.x":"Çarşıda iki adam kavgaya tutuştu, kalabalık büyüyor.","dil.kavga.c0":"Araya gir","dil.kavga.r0":"Kavgayı ayırdın; birkaç yumruk yedin ama saygı kazandın.","dil.kavga.c1":"Uzaktan izle","dil.kavga.r1":"Karışmadın, olanları izlemekle yetindin.","dil.sifa_otu.t":"Şifacının Hediyesi","dil.sifa_otu.x":"Yardım ettiğin bir şifacı, sana bir tutam şifalı ot bırakıyor.","dil.sifa_otu.c0":"Teşekkürle al","dil.sifa_otu.r0":"Şifalı otu heybene koydun. Bir gün lazım olur.","dil.kayip_cocuk.t":"Kaybolmuş Çocuk","dil.kayip_cocuk.x":"Pazarda ağlayan bir çocuk annesini arıyor. Kalabalık aldırmıyor.","dil.kayip_cocuk.c0":"Annesini bul","dil.kayip_cocuk.r0":"Çocuğu ailesine kavuşturdun; dualarını aldın.","dil.kayip_cocuk.c1":"Görmezden gel","dil.kayip_cocuk.r1":"Acelen vardı, yoluna devam ettin.","dil.kumar.t":"Han Köşesinde Kumar","dil.kumar.x":"Hanın loş köşesinde zar atılıyor. Talihini denemek ister misin?","dil.kumar.c0":"Oyna (−20 akçe)","dil.kumar.r0":"Zar senden yana döndü; kasayı topladın.","dil.kumar.c1":"Uzak dur","dil.kumar.r1":"Kumarın sonu hüsran, dedin ve geçtin.","dil.borc.t":"Dostun Borç İstiyor","dil.borc.x":"Eski bir dostun zor durumda; senden borç istiyor.","dil.borc.c0":"Borç ver (−25)","dil.borc.r0":"Dostuna el uzattın; mertliğin konuşuldu.","dil.borc.c1":"Reddet","dil.borc.r1":"Kesen sıkıydı; geri çevirdin.","dil.vaiz.t":"Meydanda Vaiz","dil.vaiz.x":"Bir vaiz halkı dine davet ediyor, bağış topluyor.","dil.vaiz.c0":"Bağış yap (−8)","dil.vaiz.r0":"Bağışını verdin; içine huzur doldu.","dil.vaiz.c1":"Dinle ve geç","dil.vaiz.r1":"Vaazı dinledin ama kesene dokunmadın.","dil.usta_teklif.t":"Ustadan Teklif","dil.usta_teklif.x":"Yaşlı bir usta çırağı olmanı, zanaatını öğretmeyi teklif ediyor.","dil.usta_teklif.c0":"Kabul et","dil.usta_teklif.r0":"Ustanın yanında çok şey öğrendin.","dil.usta_teklif.c1":"Kendi yolum var","dil.usta_teklif.r1":"Nazikçe reddettin.","dil.at_pazari.t":"At Pazarı","dil.at_pazari.x":"Bir at cambazı, sağlam görünen bir atı ucuza satıyor. Ama gözü kaçamak.","dil.at_pazari.c0":"Satın al (−25)","dil.at_pazari.r0":"At iyi çıktı; kısa sürede masrafını çıkardı.","dil.at_pazari.c1":"Şüphelen, alma","dil.at_pazari.r1":"İçin rahat etmedi, vazgeçtin.","dil.yetim.t":"Kapındaki Yetim","dil.yetim.x":"Soğuk bir gecede kapına bir yetim sığındı.","dil.yetim.c0":"İçeri al, doyur","dil.yetim.r0":"Yetimi koruyup kolladın; vicdanın aydınlandı.","dil.yetim.c1":"Geri çevir","dil.yetim.r1":"Kapını açmadın; o gece uykun kaçtı." },
  en: { "dil.dilenci.t":"A Beggar by the Road","dil.dilenci.x":"An old beggar holds out a trembling hand, asking for a morsel of bread.","dil.dilenci.c0":"Give alms (−5 coin)","dil.dilenci.r0":"You gave the beggar alms; a quiet relief passed through you.","dil.dilenci.c1":"Walk past","dil.dilenci.r1":"You turned your head and passed. His gaze followed you.","dil.kese.t":"A Purse on the Ground","dil.kese.x":"In the mud you found a purse full of coin. No owner in sight.","dil.kese.c0":"Pocket it","dil.kese.r0":"You pocketed the purse. Coin is coin; yet your conscience stung a moment.","dil.kese.c1":"Find the owner","dil.kese.r1":"You returned the purse to its owner. Your honesty was spoken of in the realm.","dil.hasta.t":"An Ailing Traveler","dil.hasta.x":"A traveler lies feverish by the road, begging for help. The sickness could spread.","dil.hasta.c0":"Help","dil.hasta.r0":"You tended the traveler; you grew a little weak, but your conscience is clear.","dil.hasta.c1":"Keep away","dil.hasta.r1":"You took no risk and went on your way.","dil.haydut.t":"A Highway Bandit","dil.haydut.x":"A bandit springs from ambush, demanding coin for passage.","dil.haydut.c0":"Pay the coin (−20)","dil.haydut.r0":"You gave what he asked and got away. Your purse is lighter.","dil.haydut.c1":"Resist","dil.haydut.r1":"You grappled with the bandit; you took a wound, but your name was called fearless.","dil.tuccar.t":"The Merchant's Offer","dil.tuccar.x":"A merchant says that if you partner in his caravan he'll double the profit. Or you go bust.","dil.tuccar.c0":"Invest (−40)","dil.tuccar.r0":"The caravan returned safe; your investment came back manifold.","dil.tuccar.c1":"Don't risk it","dil.tuccar.r1":"You declined the offer. Perhaps that was the right call.","dil.dervis.t":"A Wandering Dervish","dil.dervis.x":"A weary dervish promises words of wisdom in return for a night's lodging.","dil.dervis.c0":"Take him in","dil.dervis.r0":"You learned something from the dervish's talk (gained an attribute point).","dil.dervis.c1":"Turn him away","dil.dervis.r1":"You did not open your door; the dervish departed in silence.","dil.kavga.t":"A Brawl in the Square","dil.kavga.x":"Two men came to blows in the market; the crowd is growing.","dil.kavga.c0":"Step in","dil.kavga.r0":"You broke up the fight; took a few blows but earned respect.","dil.kavga.c1":"Watch from afar","dil.kavga.r1":"You stayed out of it, content to watch.","dil.sifa_otu.t":"The Healer's Gift","dil.sifa_otu.x":"A healer you once aided leaves you a handful of healing herbs.","dil.sifa_otu.c0":"Accept with thanks","dil.sifa_otu.r0":"You put the healing herb in your satchel. It will be needed one day.","dil.kayip_cocuk.t":"A Lost Child","dil.kayip_cocuk.x":"A crying child in the market seeks its mother. The crowd pays no heed.","dil.kayip_cocuk.c0":"Find its mother","dil.kayip_cocuk.r0":"You reunited the child with its family; you had their blessings.","dil.kayip_cocuk.c1":"Ignore it","dil.kayip_cocuk.r1":"You were in a hurry and went on your way.","dil.kumar.t":"Gambling in the Inn Corner","dil.kumar.x":"Dice are rolling in the dim corner of the inn. Care to try your luck?","dil.kumar.c0":"Play (−20 coin)","dil.kumar.r0":"The dice fell your way; you scooped up the pot.","dil.kumar.c1":"Stay away","dil.kumar.r1":"\"Gambling ends in ruin,\" you said, and moved on.","dil.borc.t":"A Friend Asks for a Loan","dil.borc.x":"An old friend is in dire straits and asks you for a loan.","dil.borc.c0":"Lend (−25)","dil.borc.r0":"You reached out to your friend; your generosity was spoken of.","dil.borc.c1":"Refuse","dil.borc.r1":"Your purse was tight; you turned him down.","dil.vaiz.t":"A Preacher in the Square","dil.vaiz.x":"A preacher calls the people to faith and gathers donations.","dil.vaiz.c0":"Donate (−8)","dil.vaiz.r0":"You gave your donation; peace filled your heart.","dil.vaiz.c1":"Listen and pass","dil.vaiz.r1":"You heard the sermon but didn't touch your purse.","dil.usta_teklif.t":"An Offer from a Master","dil.usta_teklif.x":"An old master offers to take you as apprentice and teach his craft.","dil.usta_teklif.c0":"Accept","dil.usta_teklif.r0":"You learned much at the master's side.","dil.usta_teklif.c1":"I have my own path","dil.usta_teklif.r1":"You politely declined.","dil.at_pazari.t":"The Horse Market","dil.at_pazari.x":"A horse trader sells a sturdy-looking horse cheap. But his eyes are shifty.","dil.at_pazari.c0":"Buy it (−25)","dil.at_pazari.r0":"The horse proved good; it soon paid for itself.","dil.at_pazari.c1":"Suspect it, don't buy","dil.at_pazari.r1":"It didn't sit right with you; you gave up on it.","dil.yetim.t":"An Orphan at Your Door","dil.yetim.x":"On a cold night, an orphan took shelter at your door.","dil.yetim.c0":"Take in, feed","dil.yetim.r0":"You sheltered and cared for the orphan; your conscience brightened.","dil.yetim.c1":"Turn away","dil.yetim.r1":"You did not open your door; sleep escaped you that night." },
  es: { "dil.dilenci.t":"Un Mendigo al Borde del Camino","dil.dilenci.x":"Un anciano mendigo te tiende una mano temblorosa, pidiendo un bocado de pan.","dil.dilenci.c0":"Dar limosna (−5 monedas)","dil.dilenci.r0":"Diste limosna al mendigo; un alivio te recorrió por dentro.","dil.dilenci.c1":"Pasar de largo","dil.dilenci.r1":"Volviste la cabeza y pasaste. Su mirada te siguió.","dil.kese.t":"Una Bolsa en el Suelo","dil.kese.x":"En el barro hallaste una bolsa llena de monedas. No hay dueño a la vista.","dil.kese.c0":"Guardártela","dil.kese.r0":"Te guardaste la bolsa. Moneda es moneda; pero tu conciencia punzó un instante.","dil.kese.c1":"Buscar al dueño","dil.kese.r1":"Devolviste la bolsa a su dueño. Tu honradez se comentó en el reino.","dil.hasta.t":"Un Viajero Enfermo","dil.hasta.x":"Un viajero yace febril junto al camino, pidiendo ayuda. La enfermedad podría contagiarse.","dil.hasta.c0":"Ayudar","dil.hasta.r0":"Cuidaste al viajero; quedaste algo débil, pero tu conciencia tranquila.","dil.hasta.c1":"Mantenerse lejos","dil.hasta.r1":"No corriste el riesgo y seguiste tu camino.","dil.haydut.t":"Un Bandido del Camino","dil.haydut.x":"Un bandido salta de la emboscada y exige monedas por el paso.","dil.haydut.c0":"Pagar (−20)","dil.haydut.r0":"Diste lo que pedía y escapaste. Tu bolsa quedó más liviana.","dil.haydut.c1":"Resistir","dil.haydut.r1":"Forcejeaste con el bandido; te hirió, pero tu nombre se llamó intrépido.","dil.tuccar.t":"La Oferta del Mercader","dil.tuccar.x":"Un mercader dice que si te asocias a su caravana doblará la ganancia. O te arruinas.","dil.tuccar.c0":"Invertir (−40)","dil.tuccar.r0":"La caravana volvió a salvo; tu inversión regresó multiplicada.","dil.tuccar.c1":"No arriesgar","dil.tuccar.r1":"Rechazaste la oferta. Quizá fue lo correcto.","dil.dervis.t":"Un Derviche Errante","dil.dervis.x":"Un derviche cansado promete palabras sabias a cambio de una noche de hospedaje.","dil.dervis.c0":"Acogerlo","dil.dervis.r0":"Aprendiste algo de la charla del derviche (ganaste un punto de atributo).","dil.dervis.c1":"Rechazarlo","dil.dervis.r1":"No abriste tu puerta; el derviche se alejó en silencio.","dil.kavga.t":"Riña en la Plaza","dil.kavga.x":"Dos hombres llegaron a las manos en el mercado; la multitud crece.","dil.kavga.c0":"Intervenir","dil.kavga.r0":"Separaste la pelea; recibiste algunos golpes pero ganaste respeto.","dil.kavga.c1":"Mirar de lejos","dil.kavga.r1":"No te metiste, te contentaste con mirar.","dil.sifa_otu.t":"El Regalo del Sanador","dil.sifa_otu.x":"Un sanador al que ayudaste te deja un puñado de hierbas curativas.","dil.sifa_otu.c0":"Aceptar con gratitud","dil.sifa_otu.r0":"Guardaste la hierba curativa en tu morral. Algún día hará falta.","dil.kayip_cocuk.t":"Un Niño Perdido","dil.kayip_cocuk.x":"Un niño llorando en el mercado busca a su madre. La multitud no le presta atención.","dil.kayip_cocuk.c0":"Buscar a su madre","dil.kayip_cocuk.r0":"Reuniste al niño con su familia; recibiste sus bendiciones.","dil.kayip_cocuk.c1":"Ignorarlo","dil.kayip_cocuk.r1":"Tenías prisa y seguiste tu camino.","dil.kumar.t":"Juego en el Rincón de la Posada","dil.kumar.x":"Ruedan los dados en el rincón oscuro de la posada. ¿Probar suerte?","dil.kumar.c0":"Jugar (−20 monedas)","dil.kumar.r0":"Los dados cayeron a tu favor; recogiste el bote.","dil.kumar.c1":"Mantenerse lejos","dil.kumar.r1":"\"El juego acaba en ruina\", dijiste, y seguiste.","dil.borc.t":"Un Amigo Pide Prestado","dil.borc.x":"Un viejo amigo está en apuros y te pide un préstamo.","dil.borc.c0":"Prestar (−25)","dil.borc.r0":"Tendiste la mano a tu amigo; se habló de tu nobleza.","dil.borc.c1":"Negarte","dil.borc.r1":"Tu bolsa estaba apretada; lo rechazaste.","dil.vaiz.t":"Un Predicador en la Plaza","dil.vaiz.x":"Un predicador llama al pueblo a la fe y recoge donativos.","dil.vaiz.c0":"Donar (−8)","dil.vaiz.r0":"Diste tu donativo; la paz llenó tu corazón.","dil.vaiz.c1":"Escuchar y pasar","dil.vaiz.r1":"Oíste el sermón pero no tocaste tu bolsa.","dil.usta_teklif.t":"Oferta de un Maestro","dil.usta_teklif.x":"Un viejo maestro ofrece tomarte de aprendiz y enseñarte su oficio.","dil.usta_teklif.c0":"Aceptar","dil.usta_teklif.r0":"Aprendiste mucho junto al maestro.","dil.usta_teklif.c1":"Tengo mi propio camino","dil.usta_teklif.r1":"Rechazaste con cortesía.","dil.at_pazari.t":"El Mercado de Caballos","dil.at_pazari.x":"Un tratante vende barato un caballo de aspecto robusto. Pero su mirada es esquiva.","dil.at_pazari.c0":"Comprar (−25)","dil.at_pazari.r0":"El caballo salió bueno; pronto se pagó solo.","dil.at_pazari.c1":"Sospechar, no comprar","dil.at_pazari.r1":"No te quedaste tranquilo; desististe.","dil.yetim.t":"Un Huérfano en Tu Puerta","dil.yetim.x":"En una noche fría, un huérfano se refugió en tu puerta.","dil.yetim.c0":"Acoger y alimentar","dil.yetim.r0":"Amparaste y cuidaste al huérfano; tu conciencia se iluminó.","dil.yetim.c1":"Rechazar","dil.yetim.r1":"No abriste tu puerta; esa noche perdiste el sueño." },
  pt: { "dil.dilenci.t":"Um Mendigo à Beira do Caminho","dil.dilenci.x":"Um velho mendigo estende-te uma mão trémula, pedindo um bocado de pão.","dil.dilenci.c0":"Dar esmola (−5 moedas)","dil.dilenci.r0":"Deste esmola ao mendigo; um alívio percorreu-te por dentro.","dil.dilenci.c1":"Passar ao lado","dil.dilenci.r1":"Viraste a cabeça e passaste. O olhar dele seguiu-te.","dil.kese.t":"Uma Bolsa no Chão","dil.kese.x":"Na lama encontraste uma bolsa cheia de moedas. Sem dono à vista.","dil.kese.c0":"Embolsá-la","dil.kese.r0":"Embolsaste a bolsa. Moeda é moeda; mas a tua consciência ardeu um instante.","dil.kese.c1":"Procurar o dono","dil.kese.r1":"Devolveste a bolsa ao dono. A tua honestidade foi falada no reino.","dil.hasta.t":"Um Viajante Doente","dil.hasta.x":"Um viajante jaz febril à beira do caminho, a pedir ajuda. A doença pode contagiar.","dil.hasta.c0":"Ajudar","dil.hasta.r0":"Cuidaste do viajante; ficaste algo fraco, mas com a consciência tranquila.","dil.hasta.c1":"Manter distância","dil.hasta.r1":"Não correste o risco e seguiste caminho.","dil.haydut.t":"Um Salteador de Estrada","dil.haydut.x":"Um salteador salta da emboscada e exige moedas pela passagem.","dil.haydut.c0":"Pagar (−20)","dil.haydut.r0":"Deste o que pedia e escapaste. A tua bolsa ficou mais leve.","dil.haydut.c1":"Resistir","dil.haydut.r1":"Lutaste com o salteador; ficaste ferido, mas o teu nome foi dito destemido.","dil.tuccar.t":"A Oferta do Mercador","dil.tuccar.x":"Um mercador diz que se te associares à caravana dobrará o lucro. Ou vais à falência.","dil.tuccar.c0":"Investir (−40)","dil.tuccar.r0":"A caravana voltou a salvo; o teu investimento regressou multiplicado.","dil.tuccar.c1":"Não arriscar","dil.tuccar.r1":"Recusaste a oferta. Talvez tenha sido o acertado.","dil.dervis.t":"Um Dervixe Errante","dil.dervis.x":"Um dervixe cansado promete palavras sábias em troca de uma noite de hospedagem.","dil.dervis.c0":"Acolhê-lo","dil.dervis.r0":"Aprendeste algo da conversa do dervixe (ganhaste um ponto de atributo).","dil.dervis.c1":"Recusá-lo","dil.dervis.r1":"Não abriste a porta; o dervixe afastou-se em silêncio.","dil.kavga.t":"Rixa na Praça","dil.kavga.x":"Dois homens chegaram a vias de facto no mercado; a multidão cresce.","dil.kavga.c0":"Intervir","dil.kavga.r0":"Separaste a briga; levaste alguns socos mas ganhaste respeito.","dil.kavga.c1":"Ver de longe","dil.kavga.r1":"Não te meteste, contentaste-te em ver.","dil.sifa_otu.t":"O Presente do Curandeiro","dil.sifa_otu.x":"Um curandeiro que ajudaste deixa-te um punhado de ervas curativas.","dil.sifa_otu.c0":"Aceitar com gratidão","dil.sifa_otu.r0":"Guardaste a erva curativa no bornal. Um dia fará falta.","dil.kayip_cocuk.t":"Uma Criança Perdida","dil.kayip_cocuk.x":"Uma criança a chorar no mercado procura a mãe. A multidão não liga.","dil.kayip_cocuk.c0":"Procurar a mãe","dil.kayip_cocuk.r0":"Reuniste a criança com a família; recebeste as suas bênçãos.","dil.kayip_cocuk.c1":"Ignorar","dil.kayip_cocuk.r1":"Estavas com pressa e seguiste caminho.","dil.kumar.t":"Jogo no Canto da Estalagem","dil.kumar.x":"Rolam dados no canto escuro da estalagem. Queres tentar a sorte?","dil.kumar.c0":"Jogar (−20 moedas)","dil.kumar.r0":"Os dados caíram a teu favor; arrecadaste o monte.","dil.kumar.c1":"Manter distância","dil.kumar.r1":"\"O jogo acaba em ruína\", disseste, e seguiste.","dil.borc.t":"Um Amigo Pede Emprestado","dil.borc.x":"Um velho amigo está em apuros e pede-te um empréstimo.","dil.borc.c0":"Emprestar (−25)","dil.borc.r0":"Estendeste a mão ao teu amigo; falou-se da tua nobreza.","dil.borc.c1":"Recusar","dil.borc.r1":"A tua bolsa estava apertada; recusaste.","dil.vaiz.t":"Um Pregador na Praça","dil.vaiz.x":"Um pregador chama o povo à fé e recolhe donativos.","dil.vaiz.c0":"Doar (−8)","dil.vaiz.r0":"Deste o teu donativo; a paz encheu-te o coração.","dil.vaiz.c1":"Ouvir e passar","dil.vaiz.r1":"Ouviste o sermão mas não tocaste na bolsa.","dil.usta_teklif.t":"Oferta de um Mestre","dil.usta_teklif.x":"Um velho mestre oferece tomar-te como aprendiz e ensinar o seu ofício.","dil.usta_teklif.c0":"Aceitar","dil.usta_teklif.r0":"Aprendeste muito ao lado do mestre.","dil.usta_teklif.c1":"Tenho o meu caminho","dil.usta_teklif.r1":"Recusaste com cortesia.","dil.at_pazari.t":"O Mercado de Cavalos","dil.at_pazari.x":"Um negociante vende barato um cavalo de aspeto robusto. Mas o olhar é esquivo.","dil.at_pazari.c0":"Comprar (−25)","dil.at_pazari.r0":"O cavalo saiu bom; depressa se pagou.","dil.at_pazari.c1":"Desconfiar, não comprar","dil.at_pazari.r1":"Não ficaste descansado; desististe.","dil.yetim.t":"Um Órfão à Tua Porta","dil.yetim.x":"Numa noite fria, um órfão refugiou-se à tua porta.","dil.yetim.c0":"Acolher e alimentar","dil.yetim.r0":"Abrigaste e cuidaste do órfão; a tua consciência iluminou-se.","dil.yetim.c1":"Recusar","dil.yetim.r1":"Não abriste a porta; nessa noite perdeste o sono." },
  ar: { "dil.dilenci.t":"شحّاذ على قارعة الطريق","dil.dilenci.x":"شحّاذ مُسنّ يمدّ إليك يدًا مرتجفة، يسأل لقمة خبز.","dil.dilenci.c0":"تصدّق (−5 قطع)","dil.dilenci.r0":"تصدّقت على الشحّاذ؛ سرت في صدرك راحة.","dil.dilenci.c1":"تجاوزه","dil.dilenci.r1":"أدرت وجهك ومضيت. تبعتك نظراته.","dil.kese.t":"كيسٌ على الأرض","dil.kese.x":"في الطين وجدت كيسًا مملوءًا بالقطع. لا صاحب في الأفق.","dil.kese.c0":"خذه لك","dil.kese.r0":"وضعت الكيس في جيبك. المال مال؛ لكنّ ضميرك آلمك لحظة.","dil.kese.c1":"ابحث عن صاحبه","dil.kese.r1":"أوصلت الكيس إلى صاحبه. تحدّث الناس عن أمانتك.","dil.hasta.t":"مسافر مريض","dil.hasta.x":"مسافر مُحمّ ملقى على جانب الطريق يطلب العون. قد يُعدي المرض.","dil.hasta.c0":"ساعِد","dil.hasta.r0":"اعتنيت بالمسافر؛ وهنت قليلًا لكنّ ضميرك مرتاح.","dil.hasta.c1":"ابتعد","dil.hasta.r1":"لم تخاطر ومضيت في طريقك.","dil.haydut.t":"قاطع طريق","dil.haydut.x":"لصّ يثب من الكمين ويطلب مالًا مقابل المرور.","dil.haydut.c0":"ادفع (−20)","dil.haydut.r0":"أعطيته ما طلب ونجوت. خفّ جيبك.","dil.haydut.c1":"قاوِم","dil.haydut.r1":"تصارعت مع اللصّ؛ جُرحت لكن ذُكر اسمك جسورًا.","dil.tuccar.t":"عرض التاجر","dil.tuccar.x":"تاجر يقول إن شاركته في القافلة ضاعف الربح. أو تُفلس.","dil.tuccar.c0":"استثمر (−40)","dil.tuccar.r0":"عادت القافلة سالمة؛ عاد استثمارك أضعافًا.","dil.tuccar.c1":"لا تخاطر","dil.tuccar.r1":"رفضت العرض. ربما كان ذلك الصواب.","dil.dervis.t":"درويش جوّال","dil.dervis.x":"درويش متعب يَعِد بكلمات حكمة مقابل مبيت ليلة.","dil.dervis.c0":"استضِفه","dil.dervis.r0":"تعلّمت شيئًا من حديث الدرويش (كسبت نقطة صفة).","dil.dervis.c1":"اصرفه","dil.dervis.r1":"لم تفتح بابك؛ ابتعد الدرويش بصمت.","dil.kavga.t":"شجار في الساحة","dil.kavga.x":"تشاجر رجلان في السوق؛ والحشد يكبر.","dil.kavga.c0":"تدخّل","dil.kavga.r0":"فضضت الشجار؛ نلت بعض اللكمات لكن كسبت الاحترام.","dil.kavga.c1":"راقب من بعيد","dil.kavga.r1":"لم تتدخّل، واكتفيت بالمشاهدة.","dil.sifa_otu.t":"هديّة المعالِج","dil.sifa_otu.x":"معالِج أعنته يترك لك حفنة من أعشاب الشفاء.","dil.sifa_otu.c0":"اقبل شاكرًا","dil.sifa_otu.r0":"وضعت عشبة الشفاء في جرابك. ستلزمك يومًا.","dil.kayip_cocuk.t":"طفل تائه","dil.kayip_cocuk.x":"طفل يبكي في السوق يبحث عن أمّه. والحشد لا يكترث.","dil.kayip_cocuk.c0":"ابحث عن أمّه","dil.kayip_cocuk.r0":"أعدت الطفل إلى أهله؛ نلت دعواتهم.","dil.kayip_cocuk.c1":"تجاهله","dil.kayip_cocuk.r1":"كنت مستعجلًا ومضيت في طريقك.","dil.kumar.t":"قمار في ركن الخان","dil.kumar.x":"يُرمى النرد في ركن الخان المعتم. أتجرّب حظّك؟","dil.kumar.c0":"العب (−20 قطعة)","dil.kumar.r0":"مال النرد إليك؛ جمعت ما في الكُومة.","dil.kumar.c1":"ابتعد","dil.kumar.r1":"\"القمار آخره خسران\"، قلت ومضيت.","dil.borc.t":"صديق يطلب قرضًا","dil.borc.x":"صديق قديم في ضائقة؛ يطلب منك قرضًا.","dil.borc.c0":"أقرِض (−25)","dil.borc.r0":"مددت يدك لصديقك؛ تُحُدّث عن مروءتك.","dil.borc.c1":"ارفض","dil.borc.r1":"كان كيسك ضيّقًا؛ فرفضت.","dil.vaiz.t":"واعظ في الساحة","dil.vaiz.x":"واعظ يدعو الناس إلى الدين ويجمع التبرّعات.","dil.vaiz.c0":"تبرّع (−8)","dil.vaiz.r0":"قدّمت تبرّعك؛ امتلأ قلبك سكينة.","dil.vaiz.c1":"استمع وامضِ","dil.vaiz.r1":"أصغيت للوعظ لكن لم تمسّ كيسك.","dil.usta_teklif.t":"عرض من أستاذ","dil.usta_teklif.x":"أستاذ مُسنّ يعرض أن يتّخذك صبيًّا ويعلّمك حرفته.","dil.usta_teklif.c0":"اقبل","dil.usta_teklif.r0":"تعلّمت الكثير إلى جانب الأستاذ.","dil.usta_teklif.c1":"لي طريقي","dil.usta_teklif.r1":"رفضت بلطف.","dil.at_pazari.t":"سوق الخيل","dil.at_pazari.x":"سمسار خيل يبيع حصانًا يبدو متينًا برخص. لكن عينه مراوغة.","dil.at_pazari.c0":"اشترِ (−25)","dil.at_pazari.r0":"كان الحصان جيّدًا؛ وسرعان ما عوّض ثمنه.","dil.at_pazari.c1":"ارتَب ولا تشترِ","dil.at_pazari.r1":"لم تطمئن؛ فعدلت.","dil.yetim.t":"يتيم على بابك","dil.yetim.x":"في ليلة باردة، لجأ يتيم إلى بابك.","dil.yetim.c0":"أدخِله وأطعِمه","dil.yetim.r0":"آويت اليتيم ورعيته؛ أشرق ضميرك.","dil.yetim.c1":"اصرفه","dil.yetim.r1":"لم تفتح بابك؛ هرب منك النوم تلك الليلة." },
  ru: { "dil.dilenci.t":"Нищий у дороги","dil.dilenci.x":"Старый нищий протягивает дрожащую руку, прося кусок хлеба.","dil.dilenci.c0":"Подать милостыню (−5 монет)","dil.dilenci.r0":"Ты подал нищему милостыню; по тебе разлилось тихое облегчение.","dil.dilenci.c1":"Пройти мимо","dil.dilenci.r1":"Ты отвернулся и прошёл. Его взгляд провожал тебя.","dil.kese.t":"Кошель на земле","dil.kese.x":"В грязи ты нашёл кошель, полный монет. Хозяина не видно.","dil.kese.c0":"Прикарманить","dil.kese.r0":"Ты прибрал кошель. Монета есть монета; но совесть на миг кольнула.","dil.kese.c1":"Найти хозяина","dil.kese.r1":"Ты вернул кошель хозяину. О твоей честности заговорили в краю.","dil.hasta.t":"Больной путник","dil.hasta.x":"У дороги в жару лежит путник, прося помощи. Болезнь может пристать.","dil.hasta.c0":"Помочь","dil.hasta.r0":"Ты выходил путника; немного ослаб, но совесть чиста.","dil.hasta.c1":"Держаться подальше","dil.hasta.r1":"Ты не стал рисковать и пошёл дальше.","dil.haydut.t":"Разбойник на дороге","dil.haydut.x":"Из засады выскакивает разбойник, требуя монет за проход.","dil.haydut.c0":"Заплатить (−20)","dil.haydut.r0":"Ты отдал требуемое и ушёл. Кошель полегчал.","dil.haydut.c1":"Дать отпор","dil.haydut.r1":"Ты схватился с разбойником; получил рану, но имя твоё назвали бесстрашным.","dil.tuccar.t":"Предложение купца","dil.tuccar.x":"Купец говорит, что если вступишь в долю каравана, удвоит прибыль. Или прогоришь.","dil.tuccar.c0":"Вложить (−40)","dil.tuccar.r0":"Караван вернулся цел; вложение вернулось многократно.","dil.tuccar.c1":"Не рисковать","dil.tuccar.r1":"Ты отклонил предложение. Возможно, это и правильно.","dil.dervis.t":"Странствующий дервиш","dil.dervis.x":"Усталый дервиш сулит слова мудрости в обмен на ночлег.","dil.dervis.c0":"Приютить","dil.dervis.r0":"Из беседы дервиша ты кое-чему научился (получил очко свойства).","dil.dervis.c1":"Отказать","dil.dervis.r1":"Ты не открыл дверь; дервиш молча удалился.","dil.kavga.t":"Драка на площади","dil.kavga.x":"На рынке двое сцепились; толпа растёт.","dil.kavga.c0":"Вмешаться","dil.kavga.r0":"Ты разнял драку; получил пару ударов, но заслужил уважение.","dil.kavga.c1":"Смотреть издали","dil.kavga.r1":"Ты не вмешался, довольствуясь наблюдением.","dil.sifa_otu.t":"Дар лекаря","dil.sifa_otu.x":"Лекарь, которому ты помог, оставляет тебе пучок целебных трав.","dil.sifa_otu.c0":"Принять с благодарностью","dil.sifa_otu.r0":"Ты убрал целебную траву в котомку. Однажды пригодится.","dil.kayip_cocuk.t":"Потерявшийся ребёнок","dil.kayip_cocuk.x":"Плачущий ребёнок на рынке ищет мать. Толпе нет дела.","dil.kayip_cocuk.c0":"Найти мать","dil.kayip_cocuk.r0":"Ты воссоединил ребёнка с семьёй; получил их благословения.","dil.kayip_cocuk.c1":"Не заметить","dil.kayip_cocuk.r1":"Ты спешил и пошёл дальше.","dil.kumar.t":"Игра в углу постоялого двора","dil.kumar.x":"В тёмном углу двора катают кости. Испытаешь удачу?","dil.kumar.c0":"Играть (−20 монет)","dil.kumar.r0":"Кости легли в твою пользу; ты сгрёб банк.","dil.kumar.c1":"Держаться подальше","dil.kumar.r1":"\"Игра кончается разорением\", — сказал ты и прошёл.","dil.borc.t":"Друг просит в долг","dil.borc.x":"Старый друг в беде и просит у тебя в долг.","dil.borc.c0":"Одолжить (−25)","dil.borc.r0":"Ты протянул другу руку; о твоём благородстве заговорили.","dil.borc.c1":"Отказать","dil.borc.r1":"Кошель был тощ; ты отказал.","dil.vaiz.t":"Проповедник на площади","dil.vaiz.x":"Проповедник зовёт народ к вере и собирает пожертвования.","dil.vaiz.c0":"Пожертвовать (−8)","dil.vaiz.r0":"Ты внёс пожертвование; сердце наполнилось покоем.","dil.vaiz.c1":"Выслушать и пройти","dil.vaiz.r1":"Ты выслушал проповедь, но кошелька не тронул.","dil.usta_teklif.t":"Предложение мастера","dil.usta_teklif.x":"Старый мастер предлагает взять тебя в подмастерья и обучить ремеслу.","dil.usta_teklif.c0":"Принять","dil.usta_teklif.r0":"Подле мастера ты многому научился.","dil.usta_teklif.c1":"У меня свой путь","dil.usta_teklif.r1":"Ты вежливо отказался.","dil.at_pazari.t":"Конный рынок","dil.at_pazari.x":"Барышник дёшево продаёт крепкого на вид коня. Но взгляд у него бегающий.","dil.at_pazari.c0":"Купить (−25)","dil.at_pazari.r0":"Конь оказался хорош; вскоре окупился.","dil.at_pazari.c1":"Заподозрить, не брать","dil.at_pazari.r1":"На душе было неспокойно; ты отказался.","dil.yetim.t":"Сирота у твоей двери","dil.yetim.x":"Холодной ночью у твоей двери укрылся сирота.","dil.yetim.c0":"Впустить, накормить","dil.yetim.r0":"Ты приютил и обогрел сироту; на душе посветлело.","dil.yetim.c1":"Прогнать","dil.yetim.r1":"Ты не открыл дверь; в ту ночь сон не шёл." },
};
