const DICT_CACHE: Partial<Record<Lang, Dict>> = {};
function dictFor(lang: Lang): Dict { return DICT_CACHE[lang] || (DICT_CACHE[lang] = (DICT_BUILDERS[lang] || DICT_BUILDERS.tr)()); }

// Hook'suz çevirici — saf modüller (lore vb.) için. Eksik anahtar TR'ye, o da yoksa anahtara düşer.
export function tFor(lang: Lang, key: string): string { return dictFor(lang)[key] ?? TR[key] ?? key; }
// %1, %2 … yer tutucularını parametrelerle doldurur (günlük/kronik kayıtları için).
export function applyParams(str: string, p?: (string | number)[], lang?: Lang): string {
  if (!p || !p.length) return str;
  if (lang === "tr") str = trApplySuffixes(str, (n) => { const v = p[n - 1]; return v == null ? "" : String(v); }); // rumor/tip gibi applyParams yolları da doğru allomorf alsın
  return str.replace(/%(\d+)/g, (_, n) => { const v = p[+n - 1]; return v == null ? "" : String(v); });
}

// Günlük/olay parametreleri — etiketli isimler render anında dile çözülür:
//  { i: "demir" } → eşya adı · { pl: "Yenişehir" } → yer adı · { c: ["çiftçi", 5] } → meslek unvanı · { pr: "çiftçi" } → meslek adı
const HOUSE_POOLS_I: Record<Lang, string[]> = {
  tr: ["Karaoğulları","Akhanlılar","Demiroğulları","Şahinoğulları","Bozkurtlar","Yıldızoğulları","Çelikhanlar","Aslanoğulları","Toprakoğulları","Gümüşhanlılar","Kayıoğulları","Doğanoğulları"],
  en: ["Blackmane","Ironhold","Falconcrest","Greywolf","Starhaven","Steelborn","Lionheart","Earthford","Silverhall","Hawkwind","Oakenshield","Ravenscar"],
  es: ["Casa Cuervo","Casa Halcón","Casa de Hierro","Casa Lobo","Casa Estrella","Casa Acero","Casa León","Casa Tierra","Casa Plata","Casa Águila","Casa Roble","Casa Toro"],
  pt: ["Casa Corvo","Casa Falcão","Casa do Ferro","Casa Lobo","Casa Estrela","Casa Aço","Casa Leão","Casa Terra","Casa Prata","Casa Águia","Casa Carvalho","Casa Touro"],
  ar: ["بنو غُراب","آل الصقر","بنو الحديد","بنو الذئب","آل النجم","بنو الفولاذ","آل الأسد","بنو الأرض","آل الفضّة","بنو النسر","آل البلّوط","بنو الثور"],
  ru: ["Воронцовы","Соколовы","Железновы","Волковы","Звездины","Стальновы","Львовы","Земцовы","Серебровы","Орловы","Дубовы","Турановы"],
};
export type EvtParam = string | number | { lk: string } | { i: string } | { pl: string } | { c: [string, number] } | { pr: string } | { q: string } | { route: string[] } | { fn: [number, "erkek" | "kadın"] } | { prl: string } | { il: string } | { tk: string } | { tq: string } | { kn: ["erkek" | "kadın", number, number, number, number, string, string?] } | { kf: ["erkek" | "kadın", number, number, string?] } | { pt2: string } | { fc: string } | { wc: number } | { hn: number } | { bl: string } | { enc: string } | { opp: string } | { mev: string } | { wevt: string } | { wevw: string } | { wevl: string } | { cr: string } | { wd: number } | { wds: number[] } | { wai: string } | { invl: string } | { edul: string } | { statk: string } | { ftl: string } | { goalk: string } | { sfx: string } | { stt: string } | { dreamk: string } | { crk: string };
// Cümle içi küçük harf (Türkçe İ/I doğru iner; motorların yerel ayar desteğine güvenilmez).
export function kucukHarf(str: string, lang: Lang): string { return (lang === "tr" ? str.replace(/İ/g, "i").replace(/I/g, "ı") : str).toLowerCase(); }
function resolveEvtParam(v: EvtParam | undefined, lang: Lang, t: (k: string) => string, female = false): string {
  if (v == null) return "";
  if (typeof v === "object") {
    if ("i" in v) return t("it." + v.i);
    if ("pl" in v) return placeName(v.pl, lang);
    if ("c" in v) return careerTitleL(v.c[0], v.c[1], lang);
    if ("pr" in v) return professionNameL(v.pr, lang);
    if ("prl" in v) return kucukHarf(professionNameL(v.prl, lang), lang); // cümle içinde meslek adı (küçük harf)
    if ("il" in v) return kucukHarf(t("it." + v.il), lang); // cümle içinde mal adı (küçük harf)
    if ("tk" in v) return kucukHarf(t(v.tk), lang); // çevrilmiş etiket (cümle içi)
    if ("tq" in v) return "«" + t(v.tq) + "»"; // kişinin kendi sözü (anı)
    if ("q" in v) return t("q." + v.q);
    if ("route" in v) return v.route.map((x) => placeName(x, lang)).join(" → ");
    if ("fn" in v) { const pool = NAME_POOLS[lang] || NAME_POOLS.tr; const arr = v.fn[1] === "erkek" ? pool.m : pool.f; return arr[(v.fn[0] >>> 0) % arr.length]; }
    if ("kn" in v || "kf" in v) { // nüfustaki gerçek kişinin adı: kaydındaki ad değeri/tohumu dile göre çözülür (lib/nufus kisiAdi ile birebir)
      const a = "kn" in v ? v.kn : v.kf; const pool = NAME_POOLS[lang] || NAME_POOLS.tr; const arr = a[0] === "erkek" ? pool.m : pool.f;
      const sabitAd = "kn" in v ? v.kn[6] : v.kf[3];
      const ilk = sabitAd ? sabitAd : a[1] >= 0 ? arr[Math.min(arr.length - 1, Math.floor((a[1] / 4294967296) * arr.length))] : arr[(a[2] >>> 0) % arr.length];
      if (!("kn" in v)) return ilk;
      const n = v.kn; const sy = n[5] ? n[5] : soyadCinsli(n[3] >= 0 ? pool.s[Math.min(pool.s.length - 1, Math.floor((n[3] / 4294967296) * pool.s.length))] : pool.s[(n[4] >>> 0) % pool.s.length], lang, n[0]);
      return ilk + " " + sy;
    }
    if ("pt2" in v) return t("pt." + v.pt2); // mülk tipi adı
    if ("fc" in v) return t("fac." + v.fc + ".n"); // fraksiyon adı
    if ("wc" in v) return t("trav.who." + v.wc); // yol arkadaşı türü
    if ("hn" in v) { const hp = HOUSE_POOLS_I[lang] || HOUSE_POOLS_I.tr; return hp[v.hn] ?? HOUSE_POOLS_I.tr[v.hn] ?? ""; }
    if ("bl" in v) return t("beylik." + v.bl);
    if ("enc" in v) return t("enc." + v.enc + ".t");
    if ("opp" in v) return t("opp." + v.opp + ".t");
    if ("mev" in v) return t("mev." + v.mev); // pazar olayı haberi
    if ("wevt" in v) return t("wev." + v.wevt + ".t"); // iş olayı başlığı
    if ("wevw" in v) { const wk = "wev." + v.wevw + ".win"; if (female) { const fv = t(wk + ".f"); if (fv !== wk + ".f") return fv; } return t(wk); } // iş olayı başarı (dişil varyant varsa o)
    if ("wevl" in v) { const wk = "wev." + v.wevl + ".lose"; if (female) { const fv = t(wk + ".f"); if (fv !== wk + ".f") return fv; } return t(wk); } // iş olayı başarısızlık (dişil varyant varsa o)
    if ("cr" in v) return t("crime." + v.cr + ".l"); // suç adı
    if ("wd" in v) return t("wound." + v.wd); // yaralanma adı
    if ("wds" in v) return v.wds.map((x) => t("wound." + x)).join(", "); // iyileşen yaralar listesi
    if ("wai" in v) { const wk = "whoami." + v.wai; if (female) { const fv = t(wk + ".f"); if (fv !== wk + ".f") return fv; } return t(wk); } // kim olduğun (aynadaki) — kadın için dişil varyant
    if ("invl" in v) return t("inv." + v.invl + ".l"); // nesil yatırımı adı
    if ("edul" in v) return t("edu.track." + v.edul); // süregelen eğitim yolu adı
    if ("statk" in v) return t("statn." + v.statk); // özellik adı (stat-XP)
    if ("ftl" in v) return t("fac." + v.ftl + ".tl"); // fraksiyon görev etiketi
    if ("goalk" in v) return goalL(v.goalk, lang); // NPC amacı (TR ifadeden çözülür)
    if ("sfx" in v) { if (!v.sfx) return ""; if (female) { const fv = t(v.sfx + ".f"); if (fv !== v.sfx + ".f") return fv; } return t(v.sfx); } // koşullu ek cümle (anahtarlı; dişil varyant varsa o)
    if ("stt" in v) return t("stt." + v.stt); // yerleşim kademesi adı (mezra/köy/kasaba/şehir)
    if ("dreamk" in v) return t("dream." + v.dreamk); // çocukluk hayali adı (combat/trade/crafting/social)
    if ("lk" in v) return lakapAdi(v.lk, female, t); // yaşayan lakap (dişil varyant varsa o)
    if ("crk" in v) return t("court.rank." + v.crk); // saray rütbesi adı
    return "";
  }
  return String(v);
}
// Bir olay metnini dile göre çöz: anahtar varsa çeviri + etiketli parametreler; yoksa ham metin.
// female=true: kadın oyuncu — çekimli dillerde (ru/ar) o anahtarın ".f" dişil varyantı varsa kullanılır,
// yoksa tabana (eril/nötr) düşer. Günlük hep oyuncuyu (2. şahıs) ya da adını (ölüm) anlattığı için oyuncunun cinsiyeti geçerlidir.

// ── Türkçe ek uyumu motoru: "%1'e" gibi şablon ekleri, parametre çözüldükten SONRA doğru allomorfa çevrilir.
// Kapsam: yönelme (DAT), bulunma (LOC), ayrılma (ABL), belirtme (ACC), tamlayan (GEN), vasıta (INS).
// Sayılar okunuşlarının fonolojisiyle eklenir ("3'e", "40'a", "100'e"); sesli/sert-ünsüz/kaynaştırma kuralları uygulanır.
const TR_NUM_PHON: Record<string, { lv: string; endsVowel: boolean; last: string }> = {
  "0": { lv: "ı", endsVowel: false, last: "r" }, "1": { lv: "i", endsVowel: false, last: "r" }, "2": { lv: "i", endsVowel: true, last: "i" },
  "3": { lv: "ü", endsVowel: false, last: "ç" }, "4": { lv: "ö", endsVowel: false, last: "t" }, "5": { lv: "e", endsVowel: false, last: "ş" },
  "6": { lv: "ı", endsVowel: true, last: "ı" }, "7": { lv: "i", endsVowel: true, last: "i" }, "8": { lv: "i", endsVowel: false, last: "z" },
  "9": { lv: "u", endsVowel: false, last: "z" }, "10": { lv: "o", endsVowel: false, last: "n" }, "20": { lv: "i", endsVowel: true, last: "i" },
  "30": { lv: "u", endsVowel: false, last: "z" }, "40": { lv: "ı", endsVowel: false, last: "k" }, "50": { lv: "i", endsVowel: true, last: "i" },
  "60": { lv: "ı", endsVowel: false, last: "ş" }, "70": { lv: "i", endsVowel: false, last: "ş" }, "80": { lv: "e", endsVowel: false, last: "n" },
  "90": { lv: "a", endsVowel: false, last: "n" }, "100": { lv: "ü", endsVowel: false, last: "z" }, "1000": { lv: "i", endsVowel: false, last: "n" },
};
function trPhon(word: string): { lv: string; endsVowel: boolean; last: string } {
  const w = String(word).replace(/["'”)\]]+$/g, "").trim();
  if (/^\d+$/.test(w)) { // sayı: okunuşun son birimi belirler (120 → yirmi, 300 → yüz, 45 → beş)
    let key = w;
    if (!(key in TR_NUM_PHON)) {
      const n = w.replace(/0+$/, ""); const zeros = w.length - n.length;
      if (w.endsWith("000")) key = "1000"; else if (w.endsWith("00")) key = "100";
      else if (zeros === 1) key = w.slice(-2); else key = w.slice(-1);
      if (!(key in TR_NUM_PHON)) key = w.slice(-1);
    }
    return TR_NUM_PHON[key] || { lv: "e", endsVowel: false, last: "r" };
  }
  const lw = w.toLowerCase();
  const m = lw.match(/[aeıioöuüâîû](?=[^aeıioöuüâîû]*$)/);
  const lv = m ? ({ "â": "a", "î": "i", "û": "u" } as Record<string, string>)[m[0]] || m[0] : "e"; // şapkalılar harmoniye taban ünlüyle girer (Rüzgâr→a, Dükkân→a)
  const last = lw.slice(-1);
  return { lv, endsVowel: "aeıioöuüâîû".includes(last), last };
}
function trSuffix(word: string, cls: string): string {
  const { lv, endsVowel, last } = trPhon(word);
  const back = "aıou".includes(lv); const rounded = "oöuü".includes(lv);
  const A = back ? "a" : "e";
  const I = back ? (rounded ? "u" : "ı") : (rounded ? "ü" : "i");
  const hard = "fstkçşhp".includes(last);
  switch (cls) {
    case "DAT": return (endsVowel ? "y" : "") + A;
    case "DATN": return (endsVowel ? "n" : "") + A; // 3. şahıs iyelikten sonra: hanesi'ne
    case "LOCN": return "nd" + A; // iyelikli adda bulunma: Beyliği'nde, Sancağı'nda
    case "ABLN": return "nd" + A + "n"; // iyelikli adda ayrılma: Sancağı'ndan
    case "ACCN": return "n" + I; // iyelikli adda belirtme: Loncası'nı, Kardeşliği'ni
    case "LOC": return (hard ? "t" : "d") + A;
    case "ABL": return (hard ? "t" : "d") + A + "n";
    case "ACC": return (endsVowel ? "y" : "") + I;
    case "GEN": return (endsVowel ? "n" : "") + I + "n";
    case "INS": return (endsVowel ? "y" : "") + "l" + A;
  }
  return A;
}
const TR_SUF_CLASS: [RegExp, string][] = [
  [/^(y?[ae])$/, "DAT"], [/^(n[ae])$/, "DATN"], [/^([dt][ae]n)$/, "ABL"], [/^([dt][ae])$/, "LOC"],
  [/^(y?[iıuü])$/, "ACC"], [/^(n?[iıuü]n)$/, "GEN"], [/^(y?l[ae])$/, "INS"],
  [/^(nd[ae])$/, "LOCN"], [/^(nd[ae]n)$/, "ABLN"], [/^(n[iıuü])$/, "ACCN"],
];
function trApplySuffixes(tpl: string, resolve: (n: number) => string): string {
  return tpl.replace(/%(\d+)'([a-zçğıöşü]{1,4})(?=$|[^a-zçğıöşü])/g, (m, n, suf) => {
    const cls = TR_SUF_CLASS.find(([re]) => re.test(suf));
    if (!cls) return m; // tanınmayan ek: dokunma (%1'ci gibi)
    const val = resolve(+n);
    if (!val) return m;
    return val + "'" + trSuffix(val, cls[1]);
  });
}
// Yaşayan lakap: dile ve cinsiyete göre lakap kelimesi; lakapliAd ise dile özgü sırayla adla birleştirir
// (TR "Namağlup Ali", EN "Ali the Undefeated", ES "Ali el Invicto / Ali la Invicta").
export function lakapAdi(id: string, female: boolean, t: (k: string) => string): string {
  const k = "lakap." + id;
  if (female) { const fv = t(k + ".f"); if (fv !== k + ".f") return fv; }
  return t(k);
}
export function lakapliAd(name: string, id: string | undefined, female: boolean, t: (k: string) => string): string {
  if (!id) return name;
  const l = lakapAdi(id, female, t);
  if (l === "lakap." + id) return name;
  return t("lakap.fmt").replace("%1", name).replace("%2", l);
}
export function renderEvt(k: string | undefined, fallback: string, p: EvtParam[] | undefined, lang: Lang, t: (key: string) => string, female = false): string {
  if (!k) return fallback;
  let tpl: string;
  if (female) {
    const fk = k + ".f";
    const fv = t(fk);
    tpl = fv !== fk ? fv : t(k); // dişil varyant yoksa taban
  } else {
    tpl = t(k);
  }
  if (tpl === k) return fallback; // anahtar hiçbir sözlükte yok → kayıtlı (interpolasyonlu TR) metne düş, ham anahtar gösterme
  if (!p || !p.length) return tpl;
  tpl = tpl.replace(/%b2/g, "%2").replace(/%b(?![a-z0-9])/g, "%1"); // dünya haberlerinin beylik yer tutucuları (%b, %b2) sıralı parametreye eşlenir
  if (lang === "tr") tpl = trApplySuffixes(tpl, (n) => resolveEvtParam(p[n - 1], lang, t, female)); // ekli yer tutucular önce, doğru allomorfla
  return tpl.replace(/%(\d+)/g, (_, n) => resolveEvtParam(p[+n - 1], lang, t, female));
}

interface Ctx { lang: Lang; rtl: boolean; setLang: (l: Lang) => void; t: (key: string) => string; }
const LangContext = createContext<Ctx | null>(null);

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>("tr");
  useEffect(() => { (async () => { try { const v = await AsyncStorage.getItem(KEY); if (v && DICT_BUILDERS[v as Lang]) setLangState(v as Lang); } catch {} })(); }, []);
  const setLang = useCallback((l: Lang) => { setLangState(l); AsyncStorage.setItem(KEY, l).catch(() => {}); }, []);
  const t = useCallback((key: string) => dictFor(lang)[key] ?? TR[key] ?? key, [lang]);
  const rtl = LANGS.find((l) => l.code === lang)?.rtl ?? false;
  return <LangContext.Provider value={{ lang, rtl, setLang, t }}>{children}</LangContext.Provider>;
}
export function useI18n(): Ctx {
  const c = useContext(LangContext);
  if (!c) throw new Error("useI18n must be used within LanguageProvider");
  return c;
}
